import { useQuery } from "@tanstack/react-query"
import policyEndpoints from "../endpoint/policy"
import authGet from "../methods/authGet"

export const GET_PARTNERS_LIST = 'GET_PARTNERS_LIST'
export const GET_PRODUCTS_LIST = 'GET_PRODUCTS_LIST'

export const useGetPartnersList = () => {
  return useQuery({
    queryKey: [GET_PARTNERS_LIST],
    queryFn: () => authGet({ url: policyEndpoints.getPartnersList }),
    select: (data) => data?.data?.data
  })
}

export const useGetProductsList = () => {
  return useQuery({
    queryKey: [GET_PRODUCTS_LIST],
    queryFn: () => authGet({ url: policyEndpoints.getProductsList }),
    select: (data) => data?.data?.data
  })
}
