import React, { Component } from 'react'
import { HeaderStyle, HeaderBorderStyle } from './styledComponent.style'
import { APP_COLORS } from '../../constants/colors'

class Header extends Component {
  render() {
    const { content, color = APP_COLORS.primary} = this.props

    return (
      <div>
        <HeaderStyle>
          {content}
        </HeaderStyle>
        <HeaderBorderStyle color={color} />
      </div>
    )
  }
}

export default Header