import { startCase } from 'lodash'
import { InsuredTableStyle } from './component.style'
import { Header } from '../../../../../components/StyledComponents'
import { Table } from 'antd'

export const toInsuredRows = (insuredDetails = []) =>
  Array.isArray(insuredDetails) ? insuredDetails : [insuredDetails]

// Columns follow the backend response: every key present in the data
// becomes a column, first-seen order preserved. ticket_id -> 'Ticket Id'.
export const buildColumns = (insuredDetails = []) => {
  const keys = []
  toInsuredRows(insuredDetails).forEach((row) => {
    Object.keys(row || {}).forEach((key) => {
      if (!keys.includes(key)) keys.push(key)
    })
  })
  return keys.map((key) => ({
    title: startCase(key),
    key,
    dataIndex: key
  }))
}

export function InsuredTable({ insuredDetails = [] }) {
  const rows = toInsuredRows(insuredDetails)

  return (
    <InsuredTableStyle>
      <Header content='INSURED' />
      <Table
        dataSource={rows}
        columns={buildColumns(rows)}
        scroll={{
          x: true
        }}
      />
    </InsuredTableStyle>
  )
}

export default InsuredTable
