import React from 'react'
import { SearchOutlined } from '@ant-design/icons'
import FilterText from './filterText'

export const ColumnSearchProps = (props, key, type) => {
  return {
    filterDropdown: ({ setSelectedKeys, selectedKeys, confirm }) => (
      <div className='filter-dropdown'>
        {renderSearchProps(props, type, key, setSelectedKeys, selectedKeys, confirm)}
      </div >
    ),
    filterIcon: filtered => <SearchOutlined className='search-icon' style={{ color: filtered ? '#1890ff' : undefined }} />,
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => props.searchInput && props.searchInput.select(), 100)
      }
    }
  }
}

const renderSearchProps = (props, type, key, setSelectedKeys, selectedKeys, confirm) => {
  return <FilterText
    props={props}
    type={type}
    searchKey={key}
    setSelectedKeys={setSelectedKeys}
    selectedKeys={selectedKeys}
    confirm={confirm}
  />
}
