import ConfigChecker from '../../../../../components/ConfigChecker'

const CheckPermission = ({children}) => {
  return (
    <PermissionChecker requiredPermission={"view_policy_details"}>
      <ConfigChecker
        requiredConfig={"DISPLAY_POLICY_DETAILS"}
        requiredValue="1"
      >
        {children}
      </ConfigChecker>
    </PermissionChecker>)
}

