import React from "react";
import { Header } from "../../../../../components/StyledComponents";
import { BeneficaryDataWrapper } from "./component.style";

function BeneficaryData({ beneficaryData }) {
  const customizeRelationLabel = (value) => {
    return value?.replace("-", " ")
  }

  const renderKeyValue = (key, value) => {
    return (
      <div className="beneficiary-wrapper">
          <div span={4} className="data-key">
            {key}
          </div>
          <div className="data-value">{value || "-"}</div>

      </div>
    );
  };

  const { name, dob, relationship, phone_no: phoneNo, ktp, email } = beneficaryData

  return (
    <BeneficaryDataWrapper>
      <Header content="Beneficiary Data" />
      <div className="beneficiary-container">
        {renderKeyValue("Beneficiary Name", name)}
        {renderKeyValue("Beneficiary KTP", ktp)}
        {renderKeyValue("Beneficiary Birth Date", dob)}
        {renderKeyValue("Beneficiary Phone", phoneNo)}
        {renderKeyValue("Beneficiary Relationship", customizeRelationLabel(relationship))}
        {renderKeyValue("Beneficiary Email", email)}
      </div>
    </BeneficaryDataWrapper>
  );
}

export default BeneficaryData;
