import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Table, Modal } from 'antd'
import moment from 'moment-timezone'

import { NotificationsTableStyle } from './component.style'
import { Header } from '../../../../../components/StyledComponents'
import { ModalHeader } from '../../../../../components/StyledComponents/styledComponent.style'
import { APP_COLORS } from '../../../../../constants/colors'

class Notifications extends Component {
  state = {
    showContent: false,
    content: ''
  }

  onTableChange = (pagination) => {
    const { current } = pagination
    this.props.handleTableChange(current)
  }

  render() {
    const { notificationsData, notificationListLoading } = this.props
    const { content, showContent } = this.state
    const { data, meta_data: metaData } = notificationsData
    const { total_records: totalRecords, per_page: perPage, page } = metaData
    const columns = [{
      title: 'Content',
      key: 'content',
      dataIndex: 'content',
      render: content => <div className='view-button' onClick={() => this.setState({ showContent: true, content })}>View</div>
    }, {
      title: 'Event',
      key: 'event',
      dataIndex: 'event'
    }, {
      title: 'Notification Type',
      key: 'notification_type',
      dataIndex: 'notification_type'
    }, {
      title: 'Status',
      key: 'status',
      dataIndex: 'status'
    }, {
      title: 'Remarks',
      key: 'remark',
      dataIndex: 'remark'
    }, {
      title: 'Receipents',
      key: 'recipient',
      dataIndex: 'recipient'
    }, {
      title: 'Subject',
      key: 'subject',
      dataIndex: 'subject'
    }, {
      title: 'Created At',
      key: 'created_at',
      dataIndex: 'created_at',
      render: createdAt => moment.utc(createdAt, 'YYYY-MM-DD HH:mm:ss').tz('Asia/Jakarta').format('lll')
    }, ]

    return (
      <NotificationsTableStyle>
        <Modal
          visible={showContent}
          onCancel={() => this.setState({ showContent: false })}
          footer={null}
          title={null}
          width={600}
          bodyStyle={{ padding: 0 }}
        >
          <ModalHeader providerColorCode={APP_COLORS.primary}>
            NOTIFICATION CONTENT
          </ModalHeader>
          <iframe title="Notification Content" width='100%' height={400} srcDoc={content} />
        </Modal>
        <Header content="NOTIFICATIONS SENT TO CUSTOMER" />
        <Table
          dataSource={data}
          columns={columns}
          onChange={this.onTableChange}
          loading={!!notificationListLoading}
          pagination={{
            total: totalRecords,
            pageSize: perPage,
            current: page
          }}
        />
      </NotificationsTableStyle>
    )
  }
}

export default connect(state => ({
  notificationListLoading: state.Loading.NOTIFICATIONS_LIST
}), {
})(Notifications)
