import { useQuery, useMutation } from "@tanstack/react-query"
import claimEndpoints from "../endpoint/claim"
import authGet from "../methods/authGet"
import authPost from "../methods/authPost"
import authPut from "../methods/authPut"

export const GET_CLAIMS = 'GET_CLAIMS'
export const GET_CLAIM_LIST_QUERY = 'GET_CLAIM_LIST_QUERY'
export const GET_TOTAL_CLAIMS_AMOUNT = 'GET_TOTAL_CLAIMS_AMOUNT'
export const GET_CLAIM_OCR_DATA = 'GET_CLAIM_OCR_DATA'
export const GET_INTERNAL_USER_LIST = 'GET_INTERNAL_USER_LIST'
export const GET_CLAIM_FILTERS = 'GET_CLAIM_FILTERS'


export const useClaimList = (query) => {
  const { page, pageSize, filters = {}, ownerId } = query
  // tab scope only applies when the user did not pick an explicit owner:
  // without this, ownerId overrides filters.owner_id and the owner filter
  // on 'assigned-to-me' silently does nothing
  const owner_id = filters.owner_id || ownerId
  return useQuery({
    queryKey: [GET_CLAIM_LIST_QUERY, { page, pageSize, filters, owner_id }],
    queryFn: () => authGet({url: claimEndpoints.getClaimList, query: {
      page_size: pageSize,
      page,
      ...filters,
      ...(owner_id ? { owner_id } : {}),
    }}),
    select: (data) => data?.data
  })
}

export const useGetClaimFilters = () => {
  return useQuery({
    queryKey: [GET_CLAIM_FILTERS],
    queryFn: () => authGet({ url: claimEndpoints.getClaimFilters }),
    select: (data) => data?.data
  })
}

export const useEmailClaimList = () => {
  return useMutation({
    mutationFn: ({ body }) => authPost({ url: claimEndpoints.emailList, body })
  })
}


export const useGetClaims = (query) => {
  const { applicationNo, page, pageSize } = query
  return useQuery({
    queryKey: [GET_CLAIMS, query],
    queryFn: () => authGet({url: claimEndpoints.getClaimList, query: {
      application_no: applicationNo,
      page,
      page_size: pageSize,
    }}),
    enabled: !!applicationNo,
    select: (data) => data?.data
  })
}

export const useGetTotalClaimsAmount = (query) => {
  const { applicationNo, status } = query
  return useQuery({
    queryKey: [GET_TOTAL_CLAIMS_AMOUNT, query],
    queryFn: () => authGet({url: claimEndpoints.getTotalClaimsAmount, query: {
      application_no: applicationNo,
      status,
    }}),
    enabled: !!applicationNo && !!status,
    select: (data) => data?.data?.data?.data?.total_settled_amount
  })
}

export const useGetClaimOcrData = (claimID) => {
  return useQuery({
    queryKey: [GET_CLAIM_OCR_DATA, claimID],
    queryFn: () => authGet({url: claimEndpoints.getClaimOcrData, query: {
      claim_id: claimID,
      source: 'controlpanel',
    }}),
    enabled: !!claimID,
    select: (data) => data?.data
  })
}

export const useGetInternalUserList = () => {
  return useQuery({
    queryKey: [GET_INTERNAL_USER_LIST],
    queryFn: () => authGet({ url: claimEndpoints.getInternalUserListUrl }),
    select: (res) => Array.isArray(res?.data) ? res.data : (res?.data?.data ?? [])
  })
}

export const useAssignOwner = () => {
  return useMutation({
    mutationFn: ({ body }) => authPut({ url: claimEndpoints.assignOwnerUrl, body })
  })
}
