import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Table, Row, Tag, Button, notification } from 'antd'
import { DownloadOutlined, FilterOutlined, CloseOutlined } from '@ant-design/icons'
import { set, pick, keys, isEqual } from 'lodash'
import moment from 'moment'

import { DataTableStyle } from './component.style'
import { TableColumns, FILTER_DISPLAY_NAME_MAP } from './constant'
import policyActions from '../../../../redux/policy/action'
import loadingActions from '../../../../../redux/loading/actions'
import errorActions from '../../../../../redux/error/actions'
import QuerySearchBuilder from '../../../../../helpers/querySearchBuilder'
import { QueryToObject } from '../../../../../helpers/queryToObject'
import DownloadDateModal from '../../../../../../src/components/DownloadDateModal'
import { APP_COLORS } from "../../../../../constants/colors";
import { useAppConfig } from '../../../../../request/query/app'

const { getPolicyList, getPolicyListCount, emailList, getPartnersList, getProductsList, emailRangeList } = policyActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class DataTable extends Component {
  state = {
    currentPage: 1,
    tableFilters: {},
    downloadModal:false,
  }

  componentDidMount() {
    const { history } = this.props
    const { location } = history
    const queryObject = QueryToObject(location.search)
    this.setState({ tableFilters: pick(queryObject, keys(FILTER_DISPLAY_NAME_MAP)) })
    this.fetch(queryObject)
    this.props.getPartnersList()
    this.props.getProductsList()
    this.props.resetLoadingRedux(['EMAIL_LIST'])
    this.props.resetErrorRedux(['EMAIL_LIST'])
  }

  componentWillReceiveProps(nextProps) {
    const { emailListLoading, emailListError, emailListMessage, emailRangeListMessage } = nextProps
    const { userEmail } = this.props
    if (emailListLoading === false) {
      if (emailListError) {
        notification['error']({ message: emailListMessage })
      } else {
        notification['success']({ message: `Policy list will be sent to ${userEmail}. Please check your inbox.` })
      }
      this.props.resetLoadingRedux(['EMAIL_LIST'])
      this.props.resetErrorRedux(['EMAIL_LIST'])
    }
    if (emailRangeListMessage === false) {
      if (emailListError) {
        notification['error']({ message: emailRangeListMessage })
      } else {
        notification['success']({ message: `Policy list will be sent to ${userEmail}. Please check your inbox.` })
      }
      this.props.resetLoadingRedux(['EMAIL_LIST_RANGE'])
      this.props.resetErrorRedux(['EMAIL_LIST_RANGE'])
    }
  }

  fetch = (filters) => {
    const { history } = this.props
    const { location } = history
    const query = {
      limit: 10,
      ...filters
    }
    const searchQuery = QuerySearchBuilder(query)
    history.push({ pathname: location.pathname, search: searchQuery })
    this.props.getPolicyList({
      query: {
        ...query
      }
    })
    this.props.getPolicyListCount({
      query: {
        ...query
      }
    })
  }

  handleClearFilter = () => {
    this.setState({ tableFilters: {} })
    this.fetch()
  }

  handleClickDetail = (id) => {
    this.props.history.push({ pathname: `policy/${id}`, search: '' })
  }

  removeFilter = key => {
    const { tableFilters } = this.state
    delete tableFilters[key]
    this.setState({ tableFilters })
    this.fetch({
      ...tableFilters
    })
  }

  downloadList = (e, filter) => {
    const { startDate, endDate } = e
    const { tableFilters } = this.state
    if (filter !== 'today') {
     // Range download
      let start = startDate || tableFilters.createdatStart
      let end = endDate || tableFilters.createdatEnd
      start = `${moment(start).format('YYYY-MM-DD')} 00:00:00`
      end = `${moment(end).format('YYYY-MM-DD')} 23:59:00`
      let searchQuery = tableFilters
      searchQuery.createdatStart = start
      searchQuery.createdatEnd = end
      this.props.emailRangeList({
          query: {
            ...searchQuery
          }
        })
      this.setState({ isModalVisible: false })
      this.setState({downloadModal:false})
    } else {
      // Today download
      let searchQuery = tableFilters
      const todaysDate = moment(new Date()).format('YYYY-MM-DD')
      const start = `${todaysDate} 00:00:00`
      const end = `${todaysDate} 23:59:00`
      searchQuery = {
        createdatStart: start.toString(),
        createdatEnd: end.toString()
      }
      this.props.emailList({
        query: {
          ...searchQuery
        }
      })
    }
  }

  handleTableChange = (pagination) => {
    const { current } = pagination
    const { policyList = {} } = this.props
    const { metadata = {} } = policyList
    const { limit, offset } = metadata
    const displayedCurrent = (parseInt(offset) + parseInt(limit)) / parseInt(limit)
    if (current === displayedCurrent) return
    const { tableFilters } = this.state
    this.setState({ currentPage: current })
    this.fetch({
      ...tableFilters,
      offset: (current - 1) * 10
    })
  }

  handleSearch = (value, key) => {
    const { tableFilters } = this.state;
    let searchValues = {}

    if (typeof (key) === 'object') {
      key.map((k, index) => set(searchValues, [k], value[index]))
    } else {
      set(searchValues, [key], value)
    }

    const filters = {
      ...tableFilters,
      ...searchValues
    }
    
    if(!value || (Array.isArray(value) && !value.length) || isEqual(tableFilters, filters)) {
      return 
    }
    this.fetch(filters)

    this.setState({ tableFilters: filters })
  }

  getProduct = (id) => {
    const filteredProduct = this.props.productsList?.filter((product) => {
      return product.id === id
    })

    return filteredProduct?.length ? filteredProduct[0].display_name : ''
  }

  render() {
    const { policyList = {}, policyListCount = {}, policyListLoading, emailListLoading } = this.props
    const { tableFilters } = this.state
    const { data = [], metadata = {} } = policyList
    const { total_records: totalRecords } = policyListCount
    const { limit, offset } = metadata

    return (
      <DataTableStyle>
        <Row justify='space-between' className='button-row'>
          <Button
            type='primary'
            icon={<FilterOutlined />}
            onClick={this.handleClearFilter}
          >
            Clear Filter
            </Button>
            <div className="download-buttons">
          <Button
            type='primary'
            icon={<DownloadOutlined />}
            onClick={(e)=>this.downloadList(e,'today')}
            loading={!!emailListLoading}
          >
            Download today's data           
            </Button>
            </div>
            <Button
            type='primary'
            icon={<DownloadOutlined />}
            onClick={(e)=> this.setState({downloadModal:true})}
            loading={!!emailListLoading}
          >
            Download data within range
            </Button>
           
        </Row>
        { this.state.downloadModal ?
                   <DownloadDateModal
                   modalHeading={'Report will be send to your Email'}
                   buttonName={'Send'}
                   colorCode={APP_COLORS.primary}
                   subHeading={'Date range: '}
                   modalVisible={this.state.downloadModal}
                   indentifier={'download'}
                   startDate={tableFilters.createdatStart}
                   endDate={tableFilters.createdatEnd}
                   range={60}
                   onCancel={()=>this.setState({downloadModal:false})}
                   onSearch={(e)=>this.downloadList(e)}
                   />: ""
                    }
        {
          Object.keys(tableFilters).length > 0 &&
          <Row className='filters-row' align='middle'>
            <div className='filters-header'>Filters Applied:</div>
            <div className='tag-container'>
              {
                Object.keys(tableFilters).map(key =>
                  <Tag
                    key={key}
                    color='geekblue'
                    onClick={() => this.removeFilter(key)}
                    closable
                    closeIcon={<CloseOutlined className='close-icon' onClick={() => this.removeFilter(key)} />}
                  >
                    {FILTER_DISPLAY_NAME_MAP[key]} : {
                      key === 'partnerproduct_id' ? 
                        this.getProduct(tableFilters[key]) : 
                        key === 'createdatStart' && tableFilters[key]  ?
                        moment(tableFilters[key]).add('420', 'minutes').format('YYYY-MM-DD') : 
                        key === 'createdatEnd' && tableFilters[key] ?
                        moment(tableFilters[key]).format('YYYY-MM-DD') : 
                        tableFilters[key]
                      }
                  </Tag>
                )
              }
            </div>
          </Row>
        }
        <Table
          dataSource={data}
          columns={TableColumns(this)}
          loading={!!policyListLoading}
          onChange={this.handleTableChange}
          rowKey='InternalID'
          scroll={{
            x: true
          }}
          pagination={{
            total: totalRecords,
            pageSize: 10,
            current: (parseInt(offset) + parseInt(limit)) / parseInt(limit)
          }}
        />
      </DataTableStyle>
    )
  }
}

const DataTableWrapped = connect(state => ({
  policyListLoading: state.Loading.GET_POLICY_LIST,
  policyList: state.Policy.policyList,
  policyListCount: state.Policy.policyListCount,
  productsList: state.Policy.productsList,
  emailListLoading: state.Loading.EMAIL_LIST,
  emailListError: state.Error.EMAIL_LIST,
  emailListMessage: state.Policy.emailListMessage,
  emailRangeListMessage: state.Policy.emailRangeListMessage
}), {
  getPolicyList,
  getPolicyListCount,
  emailList,
  getPartnersList,
  getProductsList,
  resetLoadingRedux,
  resetErrorRedux,
  emailRangeList
})(DataTable)

export default function WrappedPolicyListTable(props) {
  const { userDetails, userPermissions } = useAppConfig()
  return <DataTableWrapped userEmail={userDetails?.email ?? ''} userPermissions={userPermissions} {...props} />
}
