import React, { useState } from 'react'
import { FilterTextStyle } from './index.style'
import { Input, Button, Select, DatePicker } from 'antd'
import { SearchOutlined } from '@ant-design/icons'
import { find, get } from 'lodash'
import moment from 'moment'

import { FILTER_DISPLAY_NAME_MAP } from './filterDisplayName'
import { useGetPartnersList, useGetProductsList } from '../../request/query/policy'
import { useGetClaimFilters, useGetInternalUserList } from '../../request/query/claim'

const { Option } = Select

const FilterText = ({
  props, type, searchKey, setSelectedKeys, selectedKeys, confirm
}) => {
  const [createdAtStart, setCreatedAtStart] = useState('')
  const [createdAtEnd, setCreatedAtEnd] = useState('')

  const { data: partnersList = [], isLoading: partnerListLoading } = useGetPartnersList()
  const { data: productsList = [], isLoading: productListLoading } = useGetProductsList()
  const { data: filtersData = [], isLoading: filterListLoading } = useGetClaimFilters()
  const { data: ownerUsers = [], isLoading: ownerUsersLoading } = useGetInternalUserList()

  const submitSearch = () => {
    props.handleSearch(selectedKeys, searchKey)
    if (confirm) confirm()
  }

  const disabledStartDate = (startDate, today) => {
    return moment(startDate).isAfter(moment(createdAtEnd), 'day') || moment(startDate).isAfter(today || new Date(), 'day')
  }

  const disabledEndDate = (endDate, today) => {
    return moment(endDate).isBefore(moment(createdAtStart), 'day') || moment(endDate).isAfter(today || new Date(), 'day')
  }

  const renderInputType = () => {
    switch (type) {
      case 'partner':
        return <Select
          showSearch
          placeholder='Select Partner'
          optionFilterProp="children"
          allowClear
          loading={!!partnerListLoading}
          disabled={!!partnerListLoading}
          dropdownMatchSelectWidth={false}
          onChange={value => setSelectedKeys(value ? [value] : [])}
          filterOption={(input, option) =>
            option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
          }
        >
          {
            partnersList.map(({ name, code }) => <Option key={code} value={code}>{name}</Option>)
          }
        </Select>
      case 'product':
      case 'product_key':
        return <Select
          showSearch
          placeholder='Select product'
          optionFilterProp="children"
          allowClear
          loading={!!productListLoading}
          disabled={!!productListLoading}
          dropdownMatchSelectWidth={false}
          onChange={value => setSelectedKeys(value ? [value] : [])}
          filterOption={(input, option) =>
            option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
          }
        >
          {
            productsList.map(({ display_name: displayName, id, name }) => <Option key={id ?? name} value={type === 'product_key' ? name : id}>{displayName}</Option>)
          }
        </Select>
      case 'date-range-with-time':
        return <div>
          <DatePicker
            placeholder='Select Start Date'
            onChange={(_, dateString) => {
              let date = moment(dateString).startOf('day').utc().format('YYYY-MM-DD HH:mm:ss')
              setCreatedAtStart(date)
              setSelectedKeys(dateString ? [date, createdAtEnd] : [])
            }}
            disabledDate={(date) => disabledStartDate(moment(date).endOf('day').utc().format('YYYY-MM-DD HH:mm:ss'), moment().endOf('day').utc().format('YYYY-MM-DD HH:mm:ss'))}
          />
          <DatePicker
            placeholder='Select End Date'
            className='range-end'
            onChange={(_, dateString) => {
              let date = moment(dateString).endOf('day').utc().format('YYYY-MM-DD HH:mm:ss')
              setCreatedAtEnd(date)
              setSelectedKeys(dateString ? [createdAtStart, date] : [])
            }}
            disabledDate={(date) => disabledEndDate(moment(date).startOf('day').utc().format('YYYY-MM-DD HH:mm:ss'), moment().endOf('day').utc().format('YYYY-MM-DD HH:mm:ss'))}
          />
        </div>
      case 'date-range':
        return <div>
          <DatePicker
            placeholder='Select Start Date'
            onChange={(_, dateString) => {
              let date = `${dateString}`
              setCreatedAtStart(date)
              setSelectedKeys(dateString ? [date, createdAtEnd] : [])
            }}
            disabledDate={(date) => disabledStartDate(moment(date).format('YYYY-MM-DD'))}
          />
          <DatePicker
            placeholder='Select End Date'
            className='range-end'
            onChange={(_, dateString) => {
              let date = `${dateString}`
              setCreatedAtEnd(date)
              setSelectedKeys(dateString ? [createdAtStart, date] : [])
            }}
            disabledDate={(date) => disabledEndDate(moment(date).format('YYYY-MM-DD'))}
          />
        </div>
      case 'status':
        const statusData = find(filtersData, { name: 'status' }) || {}
        const statusValues = get(statusData, 'values', [])

        return <Select
          showSearch
          placeholder='Select Status'
          optionFilterProp="children"
          allowClear
          loading={!!filterListLoading}
          disabled={!!filterListLoading}
          dropdownMatchSelectWidth={false}
          onChange={value => setSelectedKeys(value ? [value] : [])}
          filterOption={(input, option) =>
            option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
          }
        >
          {
            Object.keys(statusValues).map((statusKey) => <Option key={statusKey} value={statusKey}>{statusValues[statusKey]}</Option>)
          }
        </Select>
      case 'owner':
        return <Select
          showSearch
          placeholder='Select Owner'
          optionFilterProp="children"
          allowClear
          loading={!!ownerUsersLoading}
          disabled={!!ownerUsersLoading}
          dropdownMatchSelectWidth={false}
          onChange={value => setSelectedKeys(value ? [value] : [])}
          filterOption={(input, option) =>
            `${option.children}`.toLowerCase().includes(input.toLowerCase())
          }
        >
          {
            ownerUsers.map(({ id, name, email }) => <Option key={id ?? email} value={String(id)}>{name || email}</Option>)
          }
        </Select>
      default:
        return <Input
          ref={node => {
            props.searchInput = node
          }}
          placeholder={`Search ${FILTER_DISPLAY_NAME_MAP[searchKey]}`}
          value={selectedKeys}
          onChange={e => setSelectedKeys(e.target.value ? e.target.value : "")}
          onPressEnter={submitSearch}
          style={{ width: 188, marginBottom: 8, display: 'block' }}
        />
    }
  }

  return (
    <FilterTextStyle>
      {renderInputType()}

      <Button
        type="primary"
        onClick={submitSearch}
        icon={<SearchOutlined />}
        className='search-button'
        size="small"
        style={{ width: 90 }}
      >
        Search
      </Button>
    </FilterTextStyle>
  )
}

export default FilterText
