import React, { Component } from 'react'
import moment from 'moment-timezone'
import { Table } from 'antd'

import { Header } from '../../../../../components/StyledComponents'
import { PaymentHistoryStyle } from './component.style'

class ChangeHistory extends Component {
  render() {
    const { changeHistoryData = [] } = this.props
    const columns = [
        {
          title: 'Field',
          dataIndex: 'field',
          key: 'field'
        }, {
          title: 'Change From',
          dataIndex: 'old_value',
          key: 'old_value'
        }, {
          title: 'Change To',
          dataIndex: 'new_value',
          key: 'new_value'
        }, {
          title: 'Changed by',
          dataIndex: 'updated_by',
          key: 'updated_by'
        }, {
          title: 'Updated On',
          dataIndex: 'created_at',
          key: 'created_at',
          render: date => date && moment.tz('Asia/Jakarta').format('YYYY-MM-DD HH:mm:ss')
        }, {
          title: 'Version',
          dataIndex: 'version',
          key: 'version'
        }, {
          title: 'Reason for changing',
          dataIndex: 'remarks',
          key: 'remarks'
        }
      ]

    return (
      <PaymentHistoryStyle>
        <Header content='CHANGE HISTORY LOG' />
        <Table
          dataSource={changeHistoryData}
          columns={columns}
          scroll={{
            x: true
          }}
        />
      </PaymentHistoryStyle>
    )
  }
}

export default ChangeHistory
