import React from 'react'
import { Header } from '../../../../../components/StyledComponents'
import { PolicyDetailColTableWrapper } from './component.style'

function PolicyDetailColTable({ policyDetailColData }) {

  const handlingTableKey = (str) => {
    var i; var frags = str.split('_')
    for (i = 0; i < frags.length; i++) {
      frags[i] = frags[i].charAt(0).toUpperCase() + frags[i].slice(1)
    }
    return frags.join(' ')
  }


  return (
    <PolicyDetailColTableWrapper>
      <Header content='POLICY HOLDER INFO' />
      <table className='table'>
        <tbody>
          {
            policyDetailColData?.map((item) => (
              <tr className='hover-effect border p-TB' key={item?.key}>
                <td className='w30 pLR key-decoration'>{handlingTableKey(item?.key)}</td>
                <td>{item?.value || '-'}</td>
              </tr>
            ))
          }
        </tbody>
      </table>
    </PolicyDetailColTableWrapper>
  )
}

export default PolicyDetailColTable