import React, { Component } from 'react'
import { PolicyHolderInfoStyle } from './component.style'
import { Header } from '../../../../../components/StyledComponents'
import { get } from 'lodash'
import { Row, Col } from 'antd'

class PolicyHolderInfo extends Component {
  renderKeyValue = (key, value) => {
    return value &&
      <Row>
        <Col span={4} className='data-key'>{key}</Col>
        <Col className='data-value'>{value}</Col>
      </Row>
  }

  render() {
    const { policyDetails } = this.props

    const Name = get(policyDetails, 'Request.name')
    const Email = get(policyDetails, 'Request.email')
    const MobileNo = get(policyDetails, 'Request.phone_no')
    const ktpNumber = (get(policyDetails, 'Request.identity_type', '') === 'KTP') ? get(policyDetails, 'Request.identity_number', '') : get(policyDetails, 'KTP', '')
    const dob = get(policyDetails, 'Request.date_of_birth') || get(policyDetails, 'Request.dob')

    return (
      <PolicyHolderInfoStyle>
        <Header content='POLICY HOLDER INFO' />
        {this.renderKeyValue('Name', Name)}
        {this.renderKeyValue('Email', Email)}
        {this.renderKeyValue('Phone Number', MobileNo)}
        {this.renderKeyValue('KTP Number', ktpNumber)}
        {this.renderKeyValue('Date of Birth', dob)}
      </PolicyHolderInfoStyle>
    )
  }
}

export default PolicyHolderInfo