import React, { Component } from 'react'
import { FlightInformationStyle } from './component.style'
import { Header } from '../../../../../components/StyledComponents'
import { Table } from 'antd'

class FlightInformation extends Component {
  render() {
    const { flightInformationData } = this.props
    const columns = [{
      title: 'Departure Airport Code',
      key: 'airport_code',
      dataIndex: 'airport_code'
    }, {
      title: 'Destination Airport Code',
      key: 'destination_airport_code',
      dataIndex: 'destination_airport_code'
    }, {
      title: 'Departure Date',
      key: 'departure_date',
      dataIndex: 'departure_date'
    }, {
      title: 'Flight Code',
      key: 'flight_code',
      dataIndex: 'flight_code'
    }, {
      title: 'PNR',
      key: 'pnr',
      dataIndex: 'pnr'
    }]

    return (
      <FlightInformationStyle>
        <Header content='FLIGHT INFORMATION' />
        <Table
          dataSource={[flightInformationData]}
          columns={columns}
          scroll={{
            x: true
          }}
        />
      </FlightInformationStyle>
    )
  }
}

export default FlightInformation