import { Fragment, Component } from 'react'
import { connect } from 'react-redux'
import { DatePicker, Modal } from 'antd'
import moment from 'moment'
import { SendButton, EmailHeading, SubHeadingStyle, ErrorStyle, InforDivStyle, LabelStyleWrapper } from './downloadDateModal.style'

class DownloadDateModal extends Component {
  constructor (props) {
    super(props)
    this.state = {
      minDate: moment().subtract(100, 'years').toDate(),
      maxDate: moment().add(1, 'days').toDate(),
      startDate: props.startDate || '',
      endDate: props.endDate || '',
      visibleModal:props.modalVisible,
    }
  }
 
  
  onDateValueChange = (key, value) => {
    const { mobileSearch, width } = this.props
    const dateString = moment(value).format('YYYY-MM-DD')
    this.setState(
      {
        [key]: dateString
      },
      () => {
        if (width < 768) {
          if (!!this.state.endDate && !!this.state.startDate) {
            mobileSearch(this.state)
          }
        }
      }
    )
  }

  disabledStartDate = (startDate) => {
    const { endDate, minDate, maxDate } = this.state
    return (
      
      startDate.valueOf() > moment(endDate || maxDate).valueOf() ||
      startDate.valueOf() <= moment(minDate).valueOf() 
    )
  }
  disabledEndDate = (endDate) => {
    const { startDate, maxDate, minDate } = this.state
    return (
      endDate.valueOf() < moment(startDate || minDate).valueOf() ||
      endDate.valueOf() >= moment(maxDate).valueOf() ||
     this.props.indentifier==='download' ? endDate.valueOf() >= moment(startDate).add(this.props.range,'days').valueOf() ||
      endDate.valueOf() >= moment(maxDate).valueOf() ||
      endDate.valueOf() < moment(startDate || minDate).valueOf() : null
      
    )
  }

  render () {
    const { onSearch,onCancel, colorCode, width, modalHeading,buttonName, subHeading, email } = this.props
    const { startDate, endDate, visibleModal } = this.state
    let given = moment(this.state.startDate, "YYYY-MM-DD");
    let current = moment(this.state.endDate, "YYYY-MM-DD");
    let outOfBounds = moment.duration(current.diff(given)).asDays()<60;
    return (
        <Modal
        className="claimsFliter"
        visible={visibleModal}
        onCancel={()=>onCancel()}
        footer={null}
        title={<b>{modalHeading}</b>}
          >
              <div>  
             {email && <EmailHeading>Email: <br></br>{email}</EmailHeading> }

              <SubHeadingStyle>{subHeading}</SubHeadingStyle>
              </div>
             
      <Fragment>
        <InforDivStyle>
          <div className={width <= 768 ? 'positionR marginB20 marginT10' : ''}>
            <LabelStyleWrapper
              htmlFor='startDate'
              className={width <= 768 ? 'lableCss' : ''}
              colorCode={colorCode}
            >
              Start
            </LabelStyleWrapper>
            <div>
              <DatePicker
                onChange={(date) => {
                  this.onDateValueChange('startDate', date)
                }}
                allowClear={false}
                defaultValue={startDate && moment(startDate)}
                format='YYYY-MM-DD'
                placeholder='Start Date'
                disabledDate={this.disabledStartDate}
              />
            </div>
          </div>
          <div className={width <= 768 ? 'positionR marginB20' : ''}>
            <LabelStyleWrapper
              htmlFor='endDate'
              className={width <= 768 ? 'lableCss' : ''}
              colorCode={colorCode}
            >
              End
            </LabelStyleWrapper>
            <div>
              <DatePicker
                onChange={(date) => {
                  this.onDateValueChange('endDate', date)
                }}
                allowClear={false}
                defaultValue={endDate && moment(endDate)}
                format='YYYY-MM-DD'
                placeholder='End Date'
                maxDate={moment().toDate()}
                disabledDate={this.disabledEndDate}
              />
            </div>
          </div>
        </InforDivStyle>
        {(moment.duration(current.diff(given)).asDays()<60)===false && startDate !== '' && endDate !== '' ?
              <ErrorStyle>Please select the dates within the range of 60 days</ErrorStyle> : ""
              }
          <SendButton
            type='primary'
            className='filter-button'
            onClick={() => {
              onSearch(this.state)
            }}
            colorCode={colorCode}
            outOfBounds={outOfBounds}
            disabled={(startDate === '' || endDate === '') || (moment.duration(current.diff(given)).asDays()<60)===false}
          >
            {buttonName || 'Send'}
          </SendButton>
       
      
      </Fragment>
      </Modal>
    )
  }
}

export default connect((state) => ({}), {})(DownloadDateModal)
