import React, { Component } from 'react'
import moment from 'moment-timezone'
import { Table } from 'antd'

import { Header } from '../../../../../components/StyledComponents'
import { PaymentHistoryStyle } from './component.style'

class PaymentHistory extends Component {
  render() {
    const { payments, paymentListLoading, getPaymentList, id } = this.props
    const columns = [{
      title: 'ID',
      key: 'ID',
      dataIndex: 'ID'
    }, {
      title: 'Application Number',
      key: 'ApplicationNo',
      dataIndex: 'ApplicationNo'
    }, {
      title: 'Amount',
      key: 'Amount',
      dataIndex: 'Amount'
    }, {
      title: 'Txn Ref',
      key: 'TxnRef',
      dataIndex: 'TxnRef'
    }, {
      title: 'Txn Date',
      key: 'TxnDate',
      dataIndex: 'TxnDate',
      render: date => moment.utc(date).tz('Asia/Jakarta').format('YYYY-MM-DD HH:mm:ss')
    }, {
      title: 'Coverage Start Date',
      key: 'CoverageStartDate',
      dataIndex: 'CoverageStartDate',
      render: date => moment.utc(date).format('YYYY-MM-DD HH:mm:ss')
    }, {
      title: 'Coverage End Date',
      key: 'CoverageEndDate',
      dataIndex: 'CoverageEndDate',
      render: date => moment.utc(date).format('YYYY-MM-DD HH:mm:ss')
    }]

    const handleTableChange = (pagination) => {
      const { current } = pagination
      getPaymentList({
        query: {
          id: id,
          offset: (current - 1) * 10
        }
      })
    }
  
    return (
      <PaymentHistoryStyle>
        <Header content='PAYMENT HISTORY' />
        <Table
          dataSource={payments.data || []}
          columns={columns}
          scroll={{
            x: true
          }}
          loading={!!paymentListLoading}
          onChange={handleTableChange}
          pagination={{
            total: parseInt(payments?.metadata?.total_records),
            pageSize: 10,
            current: (parseInt(payments?.metadata?.offset) + parseInt(payments?.metadata?.limit)) / parseInt(payments?.metadata?.limit)
          }}
        />
      </PaymentHistoryStyle>
    )
  }
}

export default PaymentHistory
