import React, { Component } from 'react'
import moment from 'moment-timezone'
import { Tag, Row } from 'antd'
import { get } from 'lodash'

import { PolicyDetailsStyle } from './component.style'
import { Header, DisplayKeyValue } from '../../../../../components/StyledComponents'
import { capitaliseFirstCharacter } from '../../../../../helpers/capitiliseFirstCharacter'

class PolicyDetails extends Component {
  render() {
    const { policyDetails = {} } = this.props
    const {
      PolicyState,
      ApplicationNo,
      ProductDisplayName,
      Partner,
      InsurancePolicyNo,
      CreatedAt,
      UpdatedAt,
      DocumentURL
    } = policyDetails
    const policyStartDate = get(policyDetails, 'PolicyStart.Time', '')

    return (
      <PolicyDetailsStyle>
        <Header content="POLICY DETAILS" />
        <Row>
          <Tag color='#108ee9'>STATUS: {PolicyState}</Tag>
        </Row>
        <Row className='detail-container'>
          <DisplayKeyValue dataKey='Application Number' value={ApplicationNo} />
          <DisplayKeyValue dataKey='Partner' value={capitaliseFirstCharacter(Partner)} />
          <DisplayKeyValue dataKey='Product Key' value={capitaliseFirstCharacter(ProductDisplayName)} />
          <DisplayKeyValue dataKey='Policy Number' value={InsurancePolicyNo} />
          <DisplayKeyValue dataKey='Policy Start Date' value={moment(policyStartDate).tz('Asia/Jakarta').format('ll')} />
          <DisplayKeyValue dataKey='Created At' value={moment(CreatedAt).tz('Asia/Jakarta').format('ll')} />
          <DisplayKeyValue dataKey='Updated At' value={moment(UpdatedAt).tz('Asia/Jakarta').format('ll')} />
          {
            DocumentURL && DocumentURL !== 'NA' &&
            <DisplayKeyValue dataKey='Document URL' value={DocumentURL} link />
          }
        </Row>
      </PolicyDetailsStyle>
    )
  }
}

export default PolicyDetails
