import React, { Component } from 'react'
import { Table } from 'antd'
import moment from 'moment-timezone'

import { ClaimListStyle } from './component.style'
import { Header } from '../../../../../components/StyledComponents'

class ClaimList extends Component {
  render() {
    const { claimData } = this.props
    const columns = [{
      title: 'Claim Number',
      key: 'claim_no',
      dataIndex: 'claim_no'
    }, {
      title: 'Benefit',
      key: 'benefit',
      dataIndex: 'benefit'
    }, {
      title: 'Created At',
      key: 'created_at',
      dataIndex: 'created_at',
      render: value => value && moment(value, 'DD/MM/YYYY hh:mm:ss').tz('Asia/Jakarta').format('DD/MM/YYYY')
    }, {
      title: 'Status',
      key: 'status',
      dataIndex: 'status'
    }, {
      title: 'Action',
      key: 'claim_id',
      dataIndex: 'claim_id',
      align: 'center',
      render: claimID => <div className='detail-button' onClick={() => this.props.history.push(`/claim/${claimID}`)}>Detail</div>
    }]

    return (
      <ClaimListStyle>
        <Header content='CLAIM LIST' />
        <Table
          dataSource={claimData}
          columns={columns}
          rowKey='claim_id'
          scroll={{
            x: true
          }}
        />
      </ClaimListStyle>
    )
  }
}

export default ClaimList