import React, { Component } from 'react'
import { connect } from 'react-redux'
import { get } from 'lodash'
import { Button, Card, notification, Spin } from 'antd'
import { ArrowLeftOutlined } from '@ant-design/icons'

import { PolicyDetailStyle } from './index.style'
import {
  PolicyDetailsSection,
  PolicyHolderInfo,
  PaymentHistory,
  InsuredTable,
  NotificationsTable,
  ClaimListTable,
  FlightInformation,
  ChangeHistoryLog,
  EndorsementTableComponent,
  PolicyDetailColTable,
  BeneficaryData
} from '../Components'
import policyActions from '../../../../redux/policy/action'
import { DYNAMIC_ENDORSE_PACKAGES } from '../Components/constant'
import notificationActions from '../../../../redux/notifications/actions'
import loadingActions from '../../../../../redux/loading/actions'
import errorActions from '../../../../../redux/error/actions'

const { getPolicyDetails, getChangeHistoryData, getPaymentList, dynamicEndorse } = policyActions

const { getNotificationsList } = notificationActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class PolicyDetail extends Component {
  constructor(props) {
    super(props)
    this.state = {
      policyDetailColData: [],
      dynamicEndorseTriggered: false,
      dynamicEndorsePolling: false,
      dynamicEndorsePollCount: 0,
      dynamicEndorseDone: false,
    }
  }

  componentWillUnmount() {
    if (this._pollInterval) clearInterval(this._pollInterval)
  }

  componentDidMount() {
    const { match } = this.props
    const policyID = get(match, 'params.id')

    const config = JSON.parse(localStorage.getItem('config'))
    if (Array.isArray(config) && config?.length > 0) {

      const requiredConfig = [
        {
          key: "DISPLAY_ALL_POLICY_DETAILS",
          constant : "policyDetaiConfig"
        },
        {
          key: "DISPLAY_ALL_BENEFICIARY_DATA",
          constant: "beneficiaryDataConfig"
        }
      ]

      requiredConfig.forEach((item) => {
        const value = config.find((x) => x?.config_type?.name === item.key) || {}
        this.setState({
          ...this.state,
          [item.constant] : value?.value === '1'
        })
      })
    }

    this.props.getPolicyDetails({
      query: {
        id: policyID,
        er: 1,
        field: 'endorsement'
      }
    })
    this.props.getPaymentList({
      query: {
        id: policyID
      }
    })
    this.props.getChangeHistoryData({
      query: {
        internal_id: policyID
      }
    })
    this.props.getNotificationsList({
      query: {
        reference_id: policyID,
        per_page: 5,
        entity_type: 'policy'
      }
    })
    this.props.resetLoadingRedux(['GET_POLICY_DETAILS'])
    this.props.resetErrorRedux(['GET_POLICY_DETAILS'])
  }

  componentWillReceiveProps(nextProps) {
    const { policyDetailsLoading, policyDetailsError, policyDetailsMessage, paymentListLoading, paymentListError, policyDetails} = nextProps
    if (policyDetailsLoading === false && policyDetailsError) {
      notification['error']({ message: policyDetailsMessage })
      this.props.history.replace({ pathname: '/policy' })
      this.props.resetLoadingRedux(['GET_POLICY_DETAILS'])
      this.props.resetErrorRedux(['GET_POLICY_DETAILS'])
    }

    if(policyDetailsLoading === false && !policyDetailsError){
      if (policyDetailsMessage?.toLowerCase() === "success") {
        const requestData = get(policyDetails, 'Request')
        const tempArray = []
        requestData && Object.keys(requestData).forEach((item) => {
          if (!(item === 'aggregate_id' || item === 'aggregate_policy_flag' || item === 'recon_date_time' || item === 'user_id' || item === 'userid' || item === 'recon_time' || item === 'category_id')) {
            const value = get(requestData, item)
            if (typeof value === 'number' || typeof value === 'string') {
              tempArray.push({
                key: item,
                value: value
              })
            }
          }
        })
        this.setState({ policyDetailColData: tempArray })

        const isGojekPA = policyDetails.Partner === 'gojek' &&
          policyDetails.ProductKey === 'personal-accident' &&
          DYNAMIC_ENDORSE_PACKAGES.includes(policyDetails.PackageCodeSlug)

        if (isGojekPA && (!policyDetails.DocumentURL || policyDetails.DocumentURL === 'NA') && !this.state.dynamicEndorseTriggered && !this.state.dynamicEndorseDone && !nextProps.dynamicEndorseLoading) {
          this.setState({ dynamicEndorseTriggered: true, dynamicEndorseDone: true })
          this.props.dynamicEndorse({ internalId: policyDetails.InternalID })
        }

        if (this.state.dynamicEndorsePolling && policyDetails.DocumentURL && policyDetails.DocumentURL !== 'NA') {
          this.stopDynamicEndorsePolling()
          notification.success({ message: 'Certificate generated successfully' })
        }
      }
    }

    if (this.state.dynamicEndorseTriggered && nextProps.dynamicEndorseLoading === false) {
      this.setState({ dynamicEndorseTriggered: false })
      if (nextProps.dynamicEndorseError) {
        notification.error({ message: nextProps.dynamicEndorseMessage || 'Failed to trigger certificate generation' })
      } else {
        this.startDynamicEndorsePolling()
      }
    }


    if (!paymentListLoading && paymentListError) {
      notification['error']({ message: "Error while fetching payment list" })
      this.props.resetErrorRedux(['GET_PAYMENT_LIST'])
    }
  }

  startDynamicEndorsePolling = () => {
    const MAX_POLLS = 6
    const { match } = this.props
    const policyID = get(match, 'params.id')
    this.setState({ dynamicEndorsePolling: true, dynamicEndorsePollCount: 0 })
    this._pollInterval = setInterval(() => {
      const { dynamicEndorsePollCount } = this.state
      if (dynamicEndorsePollCount >= MAX_POLLS) {
        this.stopDynamicEndorsePolling()
        notification.warning({ message: 'Certificate is still being processed, please refresh the page in a moment' })
        return
      }
      this.props.getPolicyDetails({ query: { id: policyID, er: 1, field: 'endorsement' } })
      this.setState(prev => ({ dynamicEndorsePollCount: prev.dynamicEndorsePollCount + 1 }))
    }, 5000)
  }

  stopDynamicEndorsePolling = () => {
    if (this._pollInterval) {
      clearInterval(this._pollInterval)
      this._pollInterval = null
    }
    this.setState({ dynamicEndorsePolling: false, dynamicEndorsePollCount: 0 })
  }

  handleNotificationTableChange = (page) => {
    const { match } = this.props
    const policyID = get(match, 'params.id')
    this.props.getNotificationsList({
      query: {
        reference_id: policyID,
        page,
        per_page: 5,
        entity_type: 'policy'
      }
    })
  }

  render() {
    const { 
      history, 
      policyDetails = {}, 
      policyDetailsLoading, 
      claimList = {}, 
      notifDetails = {}, 
      changeHistoryData = [], 
      paymentList,
      paymentListLoading,
      getPaymentList,
      match 
    } = this.props

    const { policyDetailColData, beneficiaryDataConfig , policyDetaiConfig } = this.state
     
    const policyID = get(match, 'params.id')
    const { data: claimData = [] } = claimList
    const { data: notificationData = [] } = notifDetails
    const insuredDetails = get(policyDetails, 'Request.policy_insured') || get(policyDetails, 'Request.insured') || get(policyDetails, 'Request.Insured')
    const flightInformationData = get(policyDetails, 'Request.flight_information')
    const beneficaryData = get(policyDetails, 'Request.beneficiary')

    return (
      <PolicyDetailStyle>
        <Spin spinning={!!policyDetailsLoading}>
          <Button
            type='primary'
            onClick={() => history.goBack()}
            icon={<ArrowLeftOutlined />}
          >
            Back
        </Button>
          <Card>
            <PolicyDetailsSection
              policyDetails={policyDetails}
            />
          </Card>
          <Card>
            {
              policyDetailColData && policyDetailColData?.length && policyDetaiConfig ?
                <PolicyDetailColTable policyDetailColData={policyDetailColData} />
                :
                <PolicyHolderInfo
                  policyDetails={policyDetails}
                />
            }
          </Card>
          {
            beneficaryData && beneficiaryDataConfig &&
            <Card>
              <BeneficaryData beneficaryData={beneficaryData}/>
            </Card>
          }
          {
            flightInformationData &&
            <Card>
              <FlightInformation
                flightInformationData={flightInformationData}
              />
            </Card>
          }
          {
            insuredDetails &&
            <Card>
              <InsuredTable
                insuredDetails={insuredDetails}
              />
            </Card>
          }
          <Card>
            <ChangeHistoryLog
              changeHistoryData={changeHistoryData}
            />
          </Card>
          <Card>
            <PaymentHistory
              payments={paymentList}
              paymentListLoading={paymentListLoading}
              getPaymentList={getPaymentList} 
              id={policyID}
            />
          </Card>
          {
            claimData.length > 0 &&
            <Card>
              <ClaimListTable
                claimData={claimData}
                history={history}
              />
            </Card>
          }
          {
            notificationData.length > 0 &&
            <Card>
              <NotificationsTable
                notificationsData={notifDetails}
                handleTableChange={this.handleNotificationTableChange}
              />
            </Card>
          }
          {
            policyDetails.endorsement && policyDetails.endorsement !== null && Object.keys(policyDetails.endorsement).length > 0 && 
            <Card>
              <EndorsementTableComponent endorsement={policyDetails.endorsement} />
            </Card>
          }
        </Spin>
      </PolicyDetailStyle>
    )
  }
}

export default connect(state => ({
  policyDetails: state.Policy.policyDetails,
  paymentList: state.Policy.paymentList,
  policyDetailsLoading: state.Loading.GET_POLICY_DETAILS,
  policyDetailsError: state.Error.GET_POLICY_DETAILS,
  paymentListLoading: state.Loading.GET_PAYMENT_LIST,
  paymentListError: state.Error.GET_PAYMENT_LIST,
  policyDetailsMessage: state.Policy.policyDetailsMessage,
  changeHistoryData: state.Policy.changeHistoryData,
  dynamicEndorseLoading: state.Loading.DYNAMIC_ENDORSE,
  dynamicEndorseError: state.Error.DYNAMIC_ENDORSE,
  dynamicEndorseMessage: state.Policy.dynamicEndorseMessage,

  claimList: state.Claim.claimList,

  notifDetails: state.Notification.notifDetails
}), {
  getPolicyDetails,
  getNotificationsList,
  resetLoadingRedux,
  resetErrorRedux,
  getChangeHistoryData,
  getPaymentList,
  dynamicEndorse,
})(PolicyDetail)
