import React, { useCallback } from 'react'
import { Row, Col, Table } from 'antd'
import {
  validUrl,
  capitalizeFirstLetter,
  getUrlExtension
} from '../../../../../helpers/utility'
import { Header } from '../../../../../components/StyledComponents'

import { EndorsementWrapper } from './component.style'

const EndorsementTable = ({ endorsement }) => {
  const getData = useCallback(() => {
    let dataEndorsement = []
    let columnsEndorsement = []

    if (endorsement != null) {
      for (let key in endorsement) {
        if (typeof endorsement[key] !== 'object') {
          dataEndorsement = [
            ...dataEndorsement,
            {
              nonArray: [
                {
                  key,
                  name: <strong>{capitalizeFirstLetter(key)}</strong>,
                  value:
                    (endorsement[key] === true ? 'true' : endorsement[key]) ||
                    '-'
                }
              ]
            }
          ]
        } else {
          let searchData = []
          if (endorsement[key]) {
            searchData = [endorsement[key]]
            /* eslint-disable */
            searchData.forEach((val) => {
              /* eslint-disable */
              columnsEndorsement = getTableKeys(val)
            })

            const newData = searchData.map((val, index) => {
              return {
                ...val,
                key: index
              }
            })
            dataEndorsement = [
              ...dataEndorsement,
              {
                arrayData: [...newData]
              }
            ]
          }
        }
      }
    }
    return {
      dataEndorsement,
      columnsEndorsement
    }
  }, [endorsement, capitalizeFirstLetter])
  const endorsementData = getData().dataEndorsement
  const endorsementColumns = getData.columnsEndorsement
  const getTableKeys = (val) => {
    const tableKeys = Object.keys(val)
      .sort()
      .map((key) =>
        val[key]
          ? {
              title: capitalizeFirstLetter(key),
              dataIndex: key,
              key: key
            }
          : {}
      )
    return tableKeys
  }

  const renderData = (data) => {
    const extension = getUrlExtension(data)
    switch (extension) {
      case 'jpg':
      case 'jpeg':
      case 'png':
      case 'gif':
      case 'svg':
        return (
          <a href={data} target='_blank' rel='noopener noreferrer'>
            <img src={data} height='50' width='auto' alt='' />
          </a>
        )
      case 'mp4':
        return (
          <a href={data} target='_blank' rel='noopener noreferrer'>
            Preview Video
          </a>
        )
      default:
        return data
    }
  }

  return (
    <EndorsementWrapper>
      <Header content='Endorsement Details' />
      <Row>
        <Col span={24}>
          {endorsementData.map((item, index) => {
            if (item.hasOwnProperty('nonArray')) {
              item = item.nonArray
              return (
                <div key={index}>
                  <Row className='row-style'>
                    <Col xs={12}>{item[0].key}</Col>
                    <Col xs={12}>{renderData(item[0].value)}</Col>
                  </Row>
                  <hr className='line-break-style' />
                </div>
              )
            }
            return null
          })}
          {endorsementData.map((item, index) => {
            if (item.hasOwnProperty('arrayData')) {
              const tableData = item.arrayData
              if (Array.isArray(tableData)) {
                tableData.forEach((item) => {
                  if (typeof item === 'object') {
                    Object.values(item).forEach((images, index) => {
                      const href =
                        images && validUrl(images) ? (
                          <span key={index} className='anchor'>
                            {images}
                          </span>
                        ) : (
                          images
                        )
                      Object.keys(item).forEach((key) => {
                        if (item[key] === images) {
                          item[key] = href
                        }
                      })
                    })
                  }
                })
              }
              return (
                <Table
                  key={index}
                  pagination={{ pageSize: 100 }}
                  showHeader
                  columns={endorsementColumns}
                  dataSource={tableData}
                  scroll={{ x: 1500 }}
                />
              )
            }
            return null
          })}
        </Col>
      </Row>
    </EndorsementWrapper>
  )
}

export default EndorsementTable